/** Every family in the bank, flattened, for lookup by compound id. */
export const FAMILIES = MODULES.flatMap((m) =>
  m.families.map((f) => ({ ...f, module: m.key, group: m.group })));

/** Resolve a compound family id (e.g. "T05:cost-finops"). */
export function findFamily(familyId) {
  return FAMILIES.find((f) => f.id === familyId) || null;
}

